"""Batch job runner migrated from Meridian CRM 4.2 semantics."""

from __future__ import annotations


def run_jobs(jobs: list[dict], executor) -> list[dict]:
    """Run scheduled jobs sequentially and return their attempt log.

    The executor is called once per attempt and may raise any Exception to
    indicate failure. Job failures are recorded according to each job's
    ``on_error`` policy and are never re-raised by this runner.
    """
    run_log: list[dict] = []

    for job in jobs:
        on_error = job["on_error"]
        policy = on_error["policy"]
        retries = on_error["retries"]

        attempts = 0

        if policy == "RETRY":
            for _ in range(retries + 1):
                attempts += 1
                try:
                    executor(job)
                except Exception:
                    continue
                else:
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "ok",
                            "audits": [],
                        }
                    )
                    break
            else:
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                break

            continue

        attempts = 1
        try:
            executor(job)
        except Exception:
            if policy == "CONTINUE":
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "skip",
                        "audits": ["BATCH_ROWSKIP"],
                    }
                )
                continue

            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "abort",
                    "audits": [],
                }
            )
            break
        else:
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "ok",
                    "audits": [],
                }
            )

    return run_log
